const source = $('Telegram Trigger').item.json;
const message = source.message ?? {};

const photos = Array.isArray(message.photo) ? message.photo : [];
const largestPhoto = photos[photos.length - 1] ?? {};

const chatId = String(message.chat?.id ?? '');
const userId = String(message.from?.id ?? '');
const mediaGroupId =
  message.media_group_id !== undefined
    ? String(message.media_group_id)
    : '';

const messageId = message.message_id ?? 0;
const updateId = source.update_id ?? 0;
const isAlbum = mediaGroupId !== '';

const reportKey = isAlbum
  ? `tg:${chatId}:album:${mediaGroupId}`
  : `tg:${chatId}:single:${messageId}`;

return {
  json: {
    part_key: `tg:update:${updateId}`,
    update_id: updateId,
    message_id: messageId,
    chat_id: chatId,
    user_id: userId,
    media_group_id: mediaGroupId,
    report_key: reportKey,
    caption: message.caption ?? '',
    file_id: largestPhoto.file_id ?? '',
    file_unique_id: largestPhoto.file_unique_id ?? '',
    file_size: largestPhoto.file_size ?? 0,
    received_at: new Date().toISOString(),
status: 'telegram_received',
    file_url: '',
    is_album: isAlbum,
  },
  binary: $input.item.binary,
};

const message = $json.message ?? {}
const callbackQuery = $json.callback_query ?? {}
const callbackMessage = callbackQuery.message ?? {}

const text = String(message.text ?? '').trim()
const callbackData = String(callbackQuery.data ?? '').trim()

let route = 'other'

// Сначала проверяем нажатия на кнопки
if (callbackData === 'report_add_text') {
  route = 'report_add_text'
} else if (callbackData === 'report_incomplete') {
  route = 'report_incomplete'
}

// Затем обычные сообщения
else if (Array.isArray(message.photo) && message.photo.length > 0) {
  route = 'photo'
} else if (text === '/start') {
  route = 'start'
} else if (text === '➕ Новый отчёт') {
  route = 'new_report'
} else if (text === 'ℹ️ Как отправить отчёт') {
  route = 'instructions'
} else if (text !== '') {
  route = 'text'
}

const chatId = String(
  message.chat?.id ??
  callbackMessage.chat?.id ??
  ''
)

const userId = String(
  message.from?.id ??
  callbackQuery.from?.id ??
  ''
)

return {
  json: {
    ...$json,
    route,
    chat_id: chatId,
    user_id: userId,
    incoming_text: text,
    callback_data: callbackData,
    callback_query_id: String(callbackQuery.id ?? ''),
  },
}

const message = $json.message ?? {}

const chatId = String(message.chat?.id ?? '')
const userId = String(message.from?.id ?? '')

const now = new Date()
const expiresAt = new Date(now.getTime() + 30 * 60 * 1000)

return {
  json: {
    session_key: `tg:${chatId}:user:${userId}`,
    chat_id: chatId,
    user_id: userId,
    status: 'awaiting_report',
    started_at: now.toISOString(),
    expires_at: expiresAt.toISOString(),
    report_key: '',
    updated_at: now.toISOString(),
  },
}

const message = $json.message ?? {}

const chatId = String(message.chat?.id ?? '')
const userId = String(message.from?.id ?? '')

return {
  json: {
    ...$json,
    session_key: `tg:${chatId}:user:${userId}`,
  },
}

const report = $input.first().json

const incoming = $('Determine incoming action').first().json
const newText = String(incoming.incoming_text ?? '').trim()

const oldCaption = String(report.caption ?? '').trim()
const oldSupplement = String(report.supplement_text ?? '').trim()

const combinedCaption = [oldCaption, newText]
  .filter(Boolean)
  .join('\n\nДополнение:\n')

const combinedSupplement = [oldSupplement, newText]
  .filter(Boolean)
  .join('\n\n')

const text = combinedCaption

const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean)

const missing = []

// Студия: ЖП, ГА, ГО, СЧ, РО или полное название
const hasStudio =
  /(^|[\s\n.,;:—-])(жп|га|го|сч|ро)($|[\s\n.,;:—-])/iu.test(text) ||
  /жар[\s-]*птиц|жарптиц|гагаринск|гагарина|горького|горкого|счастье|родионова/iu.test(text)

if (!hasStudio) {
  missing.push('студия')
}

// Мастер: можно «Мария Ф.» или «Мастер: Мария Ф.»
const hasMaster =
  /(?:^|\n)\s*мастер\s*[:\-]?\s*[А-ЯЁ][а-яё-]+\s+[А-ЯЁ]\.?\s*(?:\n|$)/iu.test(text) ||
  lines.some(line =>
    /^[А-ЯЁ][а-яё-]+\s+[А-ЯЁ]\.?$/u.test(line)
  )

if (!hasMaster) {
  missing.push('имя мастера и первая буква фамилии')
}

// Клиент: можно имя + фамилия или только имя
const hasClient =
  /(?:^|\n)\s*клиент\s*[:\-]?\s*[А-ЯЁ][а-яё-]+(?:\s+[А-ЯЁ][а-яё-]+)?\s*(?:\n|$)/iu.test(text) ||
  (
    lines.length >= 3 &&
    /^[А-ЯЁ][а-яё-]+(?:\s+[А-ЯЁ][а-яё-]+)?$/u.test(lines[2])
  )

if (!hasClient) {
  missing.push('имя клиента')
}

// База
const hasBase =
  /работали\s+базой|базой\s*[:\-]?\s*\S+|база\s*[:\-]?\s*\S+/iu.test(text)

if (!hasBase) {
  missing.push('название базы')
}

// Ремонты
const hasRepairs =
  /ремонт|ремонты|ремонтов/iu.test(text)

if (!hasRepairs) {
  missing.push('информация о ремонтах')
}

// Итоговое покрытие / цвет / лак
const hasFinalCoverage =
  /(?:покрытие|цвет|лак|гель[\s-]*лак)\s*[:\-]?\s*(?!наше\b|другого\b|другой\b|салона\b)\S+/iu.test(text) ||
  /luxio|люксио|art[\s-]*ex|artex|артекс/iu.test(text)

if (!hasFinalCoverage) {
  missing.push('номер или название покрытия / цвета')
}

// Время: 70 минут, 70 мин, 1 час, 1 час 20 минут, 1,5 часа, полтора часа
const hasDuration =
  /\d+[,.]?\d*\s*(?:минут|минута|минуты|мин\.?|м\.?|час|часа|часов|ч\.?)/iu.test(text) ||
  /полтора\s+часа/iu.test(text)

if (!hasDuration) {
  missing.push('время выполнения услуги')
}

const isValid = missing.length === 0

return [
  {
    json: {
      ...report,

      caption: combinedCaption,
      supplement_text: combinedSupplement,

      text_is_valid: isValid,
      validation_status: isValid ? 'valid' : 'awaiting_text',
      missing_fields_text: missing.join(', '),

      validation_message: isValid
        ? '✅ Спасибо, отчёт дополнен и сохранён'
        : `В отчёте всё ещё не хватает данных:\n\n${missing
            .map(field => `• ${field}`)
            .join('\n')}\n\nОтправьте недостающие данные ещё одним сообщением или нажмите «Не могу уточнить»`,
    },
  },
]

const report = $json

const chatId = String(report.chat_id ?? '')
const userId = String(report.user_id ?? '')

return {
  json: {
    ...report,

    session_key: `tg:${chatId}:user:${userId}`,
    chat_id: chatId,
    user_id: userId,
    report_key: String(report.report_key ?? ''),
    photo_count: Number(report.photo_count ?? 0),
    status: 'closed',
    updated_at: new Date().toISOString(),
  },
}

const report = $json

const chatId = String(report.chat_id ?? '')
const userId = String(report.user_id ?? '')

return {
  json: {
    ...report,

    session_key: `tg:${chatId}:user:${userId}`,
    chat_id: chatId,
    user_id: userId,
    report_key: String(report.report_key ?? ''),
    photo_count: Number(report.photo_count ?? 0),
    status: 'closed',
    updated_at: new Date().toISOString(),
  },
}
